package vn.codegym;import jakarta.servlet.*;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import java.io.*;@WebServlet("/users")public class UserServlet extends HttpServlet{private final UserDao dao=new UserDao();protected void doGet(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{try{if("delete".equals(r.getParameter("action")))dao.delete(Integer.parseInt(r.getParameter("id")));r.setAttribute("users",dao.all());r.getRequestDispatcher("/users.jsp").forward(r,s);}catch(Exception e){throw new ServletException(e);}}protected void doPost(HttpServletRequest r,HttpServletResponse s)throws IOException,ServletException{try{int id=r.getParameter("id")==null||r.getParameter("id").isBlank()?0:Integer.parseInt(r.getParameter("id"));dao.save(new User(id,r.getParameter("name"),r.getParameter("email"),r.getParameter("country")));s.sendRedirect("users");}catch(Exception e){throw new ServletException(e);}}}
